//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/bns_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
scwin.vScrenID = 'ULDBNS22001.xml';
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.objParam = new Object();
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : fn_SetParam
 * 설명       : 부모창에서 받은 데이터를 설정한다.
 ***********************************************/
scwin.fn_SetParam = function() {
    var prt = $c.frame.path("../");
    if (prt != undefined) {
        scwin.fn_GetPar = prt.scwin.fn_GetPar;
        scwin.fn_SetPar = prt.scwin.fn_SetPar;
    }
    if (scwin.fn_GetPar != undefined) {
        var arrPar = new Array();
        scwin.fn_GetPar(arrPar);
        scwin.objParam.ISUR_CD = arrPar[0].ISUR_CD;
        scwin.objParam.APPL_DD = arrPar[0].APPL_DD;
        scwin.objParam.APPL_TM = arrPar[0].APPL_TM;
        scwin.objParam.FILE_TP_CD_LIST = arrPar[0].FILE_TP_CD_LIST;
        scwin.objParam.SRI_BND_TP_CD = arrPar[0].SRI_BND_TP_CD;
    }
};



/********************************************** 
 * 함수명   : fn_update
 * 설명      : 파일구분 수정
 ***********************************************/
scwin.fn_update = function() {
    if (dts_DtlInfo.getTotalRow() == 0) return;

    // EFCT_RPT_INCLD_YN 값 보정.
    // 조달자금사용보고(최종) 인경우 : Y, N 의 값을 가짐.
    // 그 외의 문서는 null
    /*var EfctRptIncldYn = "";
    if( dts_DtlInfo.NameValue(1, "ATTACH_FILE_TP_CD") == "11" ){ //조달자금사용보고(최종) 인 경우..
    	if( dts_fileList.CountRow > 0 && dts_fileList.NameValue(1,"EFCT_RPT_INCLD_YN") == "T" ){
    		EfctRptIncldYn = "Y";
    	} else {
    		EfctRptIncldYn = "N";
    	}
    }*/

    var url = '/bns/FileFaxConn.do?method=updateAttachFileTpCd';
    url += '&SCREN_ID=' + scwin.vScrenID;
    url += '&SCREN_PROCES_TP_CD=' + SCREN_PROCS_TP_CD_03;
    url += '&STD_CD=' + $c.stf.getObjectValue(txb_StdCd);
    url += '&STD_CD_APPL_ID=';
    url += '&ISUR_APPL_ID=';
    url += '&REF_CONTN='; //저장항목 상세 java에서 셋팅
    url += '&CHG_RSN=' + $c.stf.getObjectValue(txb_DEL_RSN); //수정사유
    url += '&SRI_BND_APPL_KIND_CD=2'; //수정사유 저장시 ESG구분값 1:ESG채권등록 2:사후보고
    url += '&REG_ID=';
    url += '&SUPLY_FND_USE_RPT_YY=' + $c.stf.getObjectValue(cmb_SUPLY_FND_USE_RPT_YY);
    url += '&ATTACH_FILE_TP_CD=' + $c.stf.getObjectValue(rdo_AttachFileTpCd);
    url += '&ISUR_CD=' + scwin.objParam.ISUR_CD;
    url += '&APPL_DD=' + scwin.objParam.APPL_DD;
    url += '&APPL_TM=' + scwin.objParam.APPL_TM;
    url += '&APPL_ISU_SEQ=' + $c.stf.getObjectValue(txb_APPL_ISU_SEQ);
    url += '&EFCT_RPT_INCLD_YN=' + $c.stf.getObjectValue(rdo_EFCT_RPT_INCLD_YN); // 영향보고포함여부
    url += '&SUPLY_FND_USE_RPT_EXECUTE_AMT=' + $c.stf.getObjectValue(edt_SUPLY_FND_USE_RPT_EXECUTE_AMT); //집행금액
    url += '&FILE_FAX=' + 'ESG';
    trs_Update.Action = $c.lc.fn_encodeNSession(url);
    trs_Update.KeyName = "toinb_dataid4";
    trs_Update.KeyValue = "JSP(I:pInput=dts_DtlInfo,I:pFile=dts_fileList)";
    trs_Update.Post();
};


/*************************
 * 함수명   : fn_SelectAttach
 * 설명     : 파일 추가
 * argument : object
 *************************/
scwin.fn_SelectAttach = function() {
    //if (fn_InputCheck('Select') == false) return;
    if (dts_fileList.getTotalRow() == 1) {
        $c.win.alert("더이상 추가하실 수 없습니다.");
        return;
    }
    file.setValue("");
    file.open();
    if (file.getValue() != "") {
        var vFile = file.getValue();
        var vFileNm = vFile.split("\\");
        vFileNm = vFileNm[vFileNm.length - 1];
        if (vFileNm != "") {
            if (scwin.fn_CheckExtension(vFileNm)) return; // 파일 확장자 체크
            dts_fileList.insertRow();
        } else {
            return;
        }
        var rowPos = dts_fileList.getRowPosition();
        dts_fileList.setCellData(rowPos, "ISUR_CD", scwin.objParam.ISUR_CD);
        dts_fileList.setCellData(rowPos, "FILE_NM", vFileNm);
        dts_fileList.setCellData(rowPos, "FILE_URL", file.getValue());
        dts_fileList.setCellData(rowPos, "STD_CD", scwin.objParam.STD_CD);
        dts_fileList.setCellData(rowPos, "APPL_ISU_SEQ", scwin.objParam.APPL_ISU_SEQ);
        dts_fileList.setCellData(rowPos, "APPL_DD", scwin.objParam.APPL_DD);
        dts_fileList.setCellData(rowPos, "APPL_TM", scwin.objParam.APPL_TM);

        // 영향보고포함여부
        // 영향보고포함여부 기본값 True : 문서가 조달자금사용보고(최종) 인 경우.
        /*var AttachFileTpCd = dts_DtlInfo.NameValue(1, "ATTACH_FILE_TP_CD");
			if( AttachFileTpCd == "11" ){
dts_fileList.setNameString(rowPos, "EFCT_RPT_INCLD_YN","T") ;
			}*/

    }
};



/******************************
 * 함수명   : fn_CheckExtension
 * 설명     : 업로드 파일 확장자 체크 
 * argument : object
 *******************************/
scwin.fn_CheckExtension = function(fileNm) {
    //var fileExts = new Array(".hwp",".docx",".doc",".xls",".xlsx",".ppt",".pptx",".pdf",".gif",".jpg",".jpeg",".bmp",".tif",".txt",".drt",".dsd",".png");// 허가 확장자 목록
    var fileExts = new Array(".pdf"); // 허가 확장자 목록
    var vsFileNm = fileNm;
    var vsFileExts = vsFileNm.substr(vsFileNm.lastIndexOf("."), vsFileNm.length);
    var vsFlag = true;
    for (var i = 0; i < fileExts.length; i++) {
        if (fileExts[i] == vsFileExts) {
            vsFlag = false;
            break;
        }
    }
    if (vsFlag) {
        $c.win.alert("업로드할 수 없는 확장자입니다. 확인바랍니다.");
        return true;
    }
    return false;
};
scwin.gform_onload = function() {
    // 패널라운드 처리
    $c.bns.BnsPanelToGroupBox(panel_Item);
    $c.bns.BnsPanelToGroupBox(pnl_Sel);

    //오브젝트 가리기
    $c.stf.showObj(txb_APPL_ISU_SEQ, false);
    $c.stf.showObj(file, false);

    //호출파라미터설정
    scwin.fn_SetParam();

    //연도자동셋팅 (먼 미래를 위해 시간될때 개발 예정)

    //파일구분 수정항목 조회	
    var dsNm = 'SRI_FILE_APPL_LIST';
    var qryId = 'lds.stf.bnslistbzappl.select.readFileConnModAttachFileTpCd.SRIBND';
    var param;
    param += '&{P}V_ISUR_CD=' + scwin.objParam.ISUR_CD;
    param += '&{P}V_APPL_DD=' + scwin.objParam.APPL_DD;
    param += '&{P}V_APPL_TM=' + scwin.objParam.APPL_TM;
    $c.bns.fn_SearchBns(scwin.vScrenID, dts_DtlInfo, dsNm, qryId, param);

    //파일업로드 데이터셋 초기화

    //dts_fileList.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 

};
scwin.dts_DtlInfo_OnLoadError = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-0002"));
};
scwin.btn_Mod_onclick = function() {
    if (dts_DtlInfo.getTotalRow() == 0) return;
    scwin.fn_update();
};
scwin.trs_Update_OnSuccess = async function() {
    var arrPar = new Array();
    arrPar[0] = {
        MOD_YN: 'Y'
    };
    var parentFrame = $c.frame.path("../");
    scwin.fn_SetPar = parentFrame.fn_SetModAttachFileTpCd;
    scwin.fn_SetPar(arrPar);
    await $c.frame.CloseFrame();
};
scwin.trs_Update_OnFail = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A002", "수정"));
};
scwin.dts_DtlInfo_OnLoadCompleted = function(rowcount) {
    var temp = '';
    var fileTpCdList = scwin.objParam.FILE_TP_CD_LIST;

    // 조달자금사용보고(최종) 인 경우 영항보고포함여부 컬럼 보이도록한다.
    /*if(dts_DtlInfo.NameValue(1, "ATTACH_FILE_TP_CD") == "11"){
grd_fileList.setColumnProp("FILE_NM", "width",220) ;
grd_fileList.setColumnProp("FILE_COMMENT", "width",130) ;
grd_fileList.setColumnProp("EFCT_RPT_INCLD_YN", "width",100) ;
grd_fileList.setColumnProp("EFCT_RPT_INCLD_YN", "Show",true) ;
	} else {
grd_fileList.setColumnProp("FILE_NM", "width",260) ;
grd_fileList.setColumnProp("FILE_COMMENT", "width",190) ;
grd_fileList.setColumnProp("EFCT_RPT_INCLD_YN", "Show",false) ;
	}*/

    // 사후보고인경우 [보고년도,영향보고,집행금액] 보이게...
    if (dts_DtlInfo.getCellData(1, "SUPLY_FND_USE_RPT_YY") == "") {
        $c.stf.showObj(label_1, false);
        $c.stf.showObj(cmb_SUPLY_FND_USE_RPT_YY, false);
        $c.stf.showObj(label_20, false);
        $c.stf.showObj(rdo_EFCT_RPT_INCLD_YN, false);
        $c.stf.showObj(label_16, false);
        $c.stf.showObj(edt_SUPLY_FND_USE_RPT_EXECUTE_AMT, false);
    } else {
        $c.stf.showObj(label_1, true);
        $c.stf.showObj(cmb_SUPLY_FND_USE_RPT_YY, true);
    }
    var thisFileTpCd = dts_DtlInfo.getCellData(1, "ATTACH_FILE_TP_CD");

    // 지속가능연계채권과 그 외 채권의 경우 첨부파일 종류가 다르다..
    // 지속가능연계채권의 경우...
    // 사후보고문서는 자신과 기타만 활성.. 나머지 비활성.
    // 등록신청 문서는, 자신 + 자신외 등록신청세트문서 + 기타만 활성.
    if (scwin.objParam.SRI_BND_TP_CD == '4') {
        //이미 저장된 파일구분을 전달받아 disable 처리한다
        temp = "";
        if (fileTpCdList.indexOf('#5') >= 0) {
            temp += "5^등록신청서^disabled";
        } else {
            temp += "5^등록신청서";
        }
        temp += ",14^보고및검증문서(최초)^disabled,";
        if (fileTpCdList.indexOf('#17') >= 0) {
            temp += "17^관리체계^disabled";
        } else {
            temp += "17^관리체계";
        }
        temp += ",15^보고및검증문서(중간)^disabled,";
        if (fileTpCdList.indexOf('#18') >= 0) {
            temp += "18^외부검토서류^disabled";
        } else {
            temp += "18^외부검토서류";
        }
        temp += ",16^보고및검증문서(최종)^disabled,";
        if (fileTpCdList.indexOf('#13') >= 0) {
            temp += "13^투자설명서^disabled";
        } else {
            temp += "13^투자설명서";
        }
        temp += ",12^등록취소신청서^disabled,";

        // 사후보고문서는 기타 비활성
        if (thisFileTpCd == "14" || thisFileTpCd == "15" || thisFileTpCd == "16") {
            temp += "8^기타서류^disabled";
        } else {
            temp += "8^기타서류";
        }

        // 지속가능연계채권 외... 

    } else {
        //이미 저장된 파일구분을 전달받아 disable 처리한다
        temp = '';
        if (fileTpCdList.indexOf('#5') >= 0) {
            temp += "5^등록신청서^disabled";
        } else {
            temp += "5^등록신청서";
        }
        temp += ",9^조달자금사용보고(최초)^disabled,";
        if (fileTpCdList.indexOf('#6') >= 0) {
            temp += "6^조달자금서류(관리체계)^disabled";
        } else {
            temp += "6^조달자금서류(관리체계)";
        }
        temp += ",10^조달자금사용보고(중간)^disabled,";
        if (fileTpCdList.indexOf('#7') >= 0) {
            temp += "7^외부검토서류(대표자확인서)^disabled";
        } else {
            temp += "7^외부검토서류(대표자확인서)";
        }
        temp += ",11^조달자금사용보고(최종)^disabled,";

        // 사후보고문서는 기타 비활성
        if (thisFileTpCd == "9" || thisFileTpCd == "10" || thisFileTpCd == "11") {
            temp += "8^기타서류^disabled";
        } else {
            temp += "8^기타서류";
        }
        temp += ",12^등록취소신청서^disabled";
    }
    rdo_AttachFileTpCd.Format = temp;
};
scwin.btn_lineadd_onclick = function() {
    scwin.fn_SelectAttach();
};
scwin.btn_linedelete_onclick = function() {
    $c.cp.removeRow(dts_fileList, dts_fileList.getRowPosition());
};
scwin.txb_DEL_RSN_onkeyup = function() {
    //fn_DelChar(this);		

};
